export function parseCreatureTypes(typeLine: string, knownTypes?: Set<string>): string[] {
  const [typePart, subtypePart] = typeLine.split('—');
  if (!subtypePart) return [];
  // typePart is always populated: .split() on any string returns at least
  // one element, which destructures into this position.
  // Word-boundary matched, and checked against the type part only: a Battle
  // whose subtype happened to read "Creature" would otherwise slip through.
  if (!/\b(Creature|Kindred|Tribal)\b/.test(typePart!)) return [];

  const words = subtypePart.trim().split(/\s+/).filter(Boolean);
  if (!knownTypes) return words;

  const result: string[] = [];
  const seen = new Set<string>();

  const multiWordTypes = [...knownTypes]
    .filter((t) => t.includes(' '))
    .sort((a, b) => b.length - a.length);

  const checkMultiWordAt = (index: number): string | null => {
    for (const mwt of multiWordTypes) {
      const mwtWords = mwt.toLowerCase().split(/\s+/);
      if (index + mwtWords.length > words.length) continue;
      const segment = words.slice(index, index + mwtWords.length).join(' ');
      if (segment.toLowerCase() === mwt.toLowerCase()) {
        return mwt;
      }
    }
    return null;
  };

  for (let i = 0; i < words.length; i++) {
    const mwt = checkMultiWordAt(i);
    if (mwt && !seen.has(mwt)) {
      result.push(mwt);
      seen.add(mwt);
      i += mwt.split(/\s+/).length - 1;
      continue;
    }

    const word = words[i];
    if (knownTypes.has(word) && !seen.has(word)) {
      result.push(word);
      seen.add(word);
    }
  }

  return result;
}

