  it('a word that is part of a multi-word type is not kept alone', () => {
    const typesWithMultiWord = new Set(['Goblin', 'Time Lord', 'Wizard']);
    assert.deepStrictEqual(
      parseCreatureTypes('Creature — Time Wizard', typesWithMultiWord),
      ['Wizard'],
    );
  });
});

